SELECT id, symbol, interval_code, candle_open_time, latest_price, stop_loss, take_profit, atr_at_signal, atr_percent, risk_reward_ratio, candle_range_atr_multiple, atr_entry_type, atr_recommended_position_percent, final_entry_allowed, confidence_score FROM crypto_ai.trade_signal WHERE id IN (159285,159407,165415,167616,171559,176655,156721) ORDER BY symbol, candle_open_time LIMIT 10